<script setup>import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuthStore} from '../stores/auth';const username=ref('planner'),password=ref('Demo@2026'),busy=ref(false),error=ref(''),router=useRouter(),auth=useAuthStore();async function login(){busy.value=true;error.value='';try{const user=await auth.login(username.value,password.value);router.push(user.role==='OPERATOR'?'/shopfloor':'/admin')}catch(e){error.value=e.response?.data?.message||'登录失败，请检查账号'}finally{busy.value=false}}function choose(type){username.value=type;password.value='Demo@2026';login()}</script>
<template><div class="login aps-login"><div class="login-story"><div class="brand light"><div class="brand-mark">ZH</div><div><b>知华 APS</b><small>ADVANCED PLANNING & SCHEDULING</small></div></div><div class="factory-grid"><span v-for="i in 35" :key="i" :class="{on:[2,3,7,8,9,14,15,16,17,22,23,27,28,29,30,31].includes(i)}"></span></div><div class="story-copy"><span>让复杂计划得到可执行答案</span><h1>订单到资源，物料到产能，<br/>每一次排程都有约束依据。</h1><p>连接订单、产能、物料和工艺约束的智能排程底座。</p></div><div class="story-stats"><div><b>67.2%</b><span>今日计划达成</span></div><div><b>98.6%</b><span>一次合格率</span></div><div><b>86.4%</b><span>综合资源效率</span></div></div><small class="copyright">© 2026 上海如静知华信息科技有限公司</small></div><div class="login-panel"><div class="login-box"><span class="eyebrow">ZHUATECH PLANNING</span><h2>进入计划排程中心</h2><p>登录后按岗位进入排程协同端或管理端</p><label>账号</label><input v-model="username" autocomplete="username"/><label>密码</label><input v-model="password" type="password" autocomplete="current-password" @keyup.enter="login"/><div class="login-options"><label><input type="checkbox" checked/> 记住账号</label><a href="https://www.zhuatech.cn/" target="_blank">部署与授权咨询</a></div><button class="primary full" @click="login" :disabled="busy">{{busy?'正在验证…':'登录系统'}}</button><span class="login-error">{{error}}</span><div class="demo-select"><span>演示入口</span><button @click="choose('planner')"><b>计划管理端</b><small>计划 / 质量 / 资源</small></button><button @click="choose('operator')"><b>排程协同端</b><small>任务 / 反馈 / 异常</small></button></div><small class="demo-note">演示密码统一为 Demo@2026</small></div></div></div></template>
